// Local Figma development plugin. Creates a new page; never edits existing pages.
const palettes = {
  Dark: {bg:'101715',panel:'18211E',raised:'1D2924',line:'2D3C34',text:'EDF2E9',muted:'9EAFA4',accent:'BEDAA2',ink:'22331D'},
  Light: {bg:'F5F5EE',panel:'FFFEF8',raised:'ECEFE4',line:'D9DFD0',text:'23382C',muted:'647465',accent:'446C38',ink:'FFFFFF'}
};
const screens = ['Home','Search','Empty search','Memorial','Saved memorial','Map','Walking route','Visit pass','Generated pass','Gate officer','Invalid pass','Visit history','Empty history','Profile','Roles','Admin','Burial records','Lot management','Lot owner'];
const titles = {Home:'A little closer to those you love.',Search:'Find a loved one.', 'Empty search':'Find a loved one.',Memorial:'In loving memory.', 'Saved memorial':'A memory held close.',Map:'Find your way, gently.','Walking route':'Your path to remembrance.','Visit pass':'You’re always welcome.','Generated pass':'Your visit, prepared.','Gate officer':'A warm welcome at the gate.','Invalid pass':'Let’s check that pass.','Visit history':'Moments remembered.','Empty history':'Your visits start here.',Profile:'Make yourself at home.',Roles:'Choose your perspective.',Admin:'Care for every detail.','Burial records':'Preserving their stories.','Lot management':'Every lot, accounted for.','Lot owner':'A place held close.'};
const names=['Maria Santos','Jose Dela Cruz','Elena Reyes','Antonio Garcia','Rosa Mendoza'];
const locations=['Block A · Lot 024 · Grave 01','Block B · Lot 012 · Grave 02','Block A · Lot 031 · Grave 01','Block C · Lot 008 · Grave 03','Block D · Lot 016 · Grave 01'];
const links=[];const frames={};let fonts;let page;
function rgb(hex){return {r:parseInt(hex.slice(0,2),16)/255,g:parseInt(hex.slice(2,4),16)/255,b:parseInt(hex.slice(4,6),16)/255}}
function paint(hex){return [{type:'SOLID',color:rgb(hex)}]}
function box(parent,name,x,y,w,h,color,radius=12){const n=figma.createFrame();n.name=name;n.resize(w,h);n.x=x;n.y=y;n.fills=paint(color);n.cornerRadius=radius;n.clipsContent=false;parent.appendChild(n);return n}
function txt(parent,value,x,y,w,size,color,display=false,bold=false){const n=figma.createText();n.fontName=display?fonts.display:bold?fonts.bold:fonts.body;n.fontSize=size;n.characters=value;n.fills=paint(color);n.lineHeight={unit:'PERCENT',value:135};n.resize(w,Math.max(1,size*1.35));n.textAutoResize='HEIGHT';n.x=x;n.y=y;n.name=value.slice(0,65);parent.appendChild(n);return n}
function button(ctx,label,x,y,w,target,primary=false,theme=ctx.theme){const n=box(ctx.f,label,x,y,w,46,primary?ctx.c.accent:ctx.c.raised,9);txt(n,label,14,13,w-28,13,primary?ctx.c.ink:ctx.c.text,false,true);if(target)links.push({node:n,key:`${ctx.device}/${theme}/${target}`});return n}
function card(ctx,x,y,w,h,title,copy){const n=box(ctx.f,title,x,y,w,h,ctx.c.panel);n.strokes=paint(ctx.c.line);txt(n,title,22,20,w-44,19,ctx.c.text);if(copy)txt(n,copy,22,54,w-44,13,ctx.c.muted);return n}
function list(ctx,y,count=5){for(let i=0;i<count;i++){const n=box(ctx.f,`Memorial / ${names[i]}`,ctx.x,y+i*87,ctx.w,76,ctx.c.panel);txt(n,names[i],20,14,ctx.w-40,16,ctx.c.text);txt(n,locations[i],20,42,ctx.w-40,11,ctx.c.muted);if(i===0)links.push({node:n,key:`${ctx.device}/${ctx.theme}/Memorial`})}}
function ground(ctx,y,route){const h=ctx.mobile?258:330;const n=box(ctx.f,'Illustrative cemetery map',ctx.x,y,ctx.w,h,ctx.c.panel);const w=ctx.w;box(n,'Main pathway',w/2-9,18,18,h-30,ctx.c.line,0);box(n,'Cross pathway',20,h/2-9,w-40,18,ctx.c.line,0);['A','B','C','D'].forEach((b,i)=>{const bx=i%2?w*.57:w*.08,by=i<2?28:h*.58,bw=w*.34,bh=h*.29;const lot=box(n,`Block ${b}`,bx,by,bw,bh,i===0?ctx.c.accent:ctx.c.raised,8);for(let j=0;j<8;j++)box(lot,'Grave plot',12+(j%4)*(bw-24)/4,12+Math.floor(j/4)*18,Math.max(8,(bw-40)/5),11,ctx.c.line,2);txt(lot,`BLOCK ${b}`,12,bh-24,bw-24,10,i===0?ctx.c.ink:ctx.c.muted)});if(route){box(n,'Walking route / north',w/2-2,h*.27,4,h*.63,ctx.c.accent,1);box(n,'Walking route / destination',w*.26,h*.27,w*.24,4,ctx.c.accent,1)}txt(n,'MAIN ENTRANCE',w/2+16,h-25,w/2-20,9,ctx.c.muted);return h}
function shell(device,theme,screen,index,row){const mobile=device==='Mobile',c=palettes[theme],width=mobile?390:1440,height=mobile?1120:1024;const f=box(page,`${device} / ${theme} / ${screen}`,index*(width+90),row*1250,width,height,c.bg,0);f.clipsContent=true;const ctx={f,c,device,theme,mobile,x:mobile?20:294,w:mobile?350:1102};frames[`${device}/${theme}/${screen}`]=f;
  if(!mobile){box(f,'Sidebar',0,0,250,height,c.panel,0);txt(f,'evergreen',25,34,210,32,c.accent,true);txt(f,'CEMETERY & MEMORIAL',25,83,210,9,c.muted);button(ctx,'Explore roles  →',22,129,206,'Roles');[['Overview','Home'],['Find a grave','Search'],['Cemetery map','Map'],['Visit pass','Visit pass'],['Visit history','Visit history'],['My profile','Profile']].forEach(([label,to],i)=>button(ctx,label,22,207+i*60,206,to));txt(f,'A place to remember.',25,785,200,14,c.text);txt(f,'Find your way. Keep their\nmemory close.',25,819,200,12,c.muted);button(ctx,theme==='Dark'?'Switch to light mode':'Switch to dark mode',22,905,206,screen,false,theme==='Dark'?'Light':'Dark')}
  else {txt(f,'evergreen',20,22,190,28,c.accent,true);button(ctx,'Roles',269,20,101,'Roles');[['Home','Home'],['Search','Search'],['Map','Map'],['Pass','Visit pass']].forEach(([label,to],i)=>button(ctx,label,20+i*89,80,83,to));button(ctx,theme==='Dark'?'Light mode':'Dark mode',245,142,125,screen,false,theme==='Dark'?'Light':'Dark')}
  txt(f,'EVERGREEN MEMORIAL PARK',ctx.x,mobile?153:35,mobile?215:600,9,c.accent);txt(f,titles[screen],ctx.x,mobile?215:118,ctx.w,mobile?31:42,c.text,true);txt(f,'Interactive design · Fictional records',ctx.x,mobile?315:190,ctx.w,12,c.muted);txt(f,'Sample data · Illustrative map · No live transactions',ctx.x,height-32,ctx.w,10,c.muted);ctx.y=mobile?362:245;return ctx;
}
function draw(ctx,screen){const {x,w,y,mobile,c,f}=ctx;
 switch(screen){
 case 'Home':{card(ctx,x,y,w,mobile?266:248,'A MEMORY. A PLACE. A CONNECTION.','');txt(f,'Remembering starts\nwith finding.',x+24,y+55,w-48,mobile?32:43,c.text,true);txt(f,'Locate a loved one and plan a peaceful visit.',x+24,y+(mobile?155:174),w-48,13,c.muted);button(ctx,'Search a name or lot number  →',x+24,y+(mobile?204:202),w-48,'Search',true);const cy=y+(mobile?292:280);button(ctx,'Explore the grounds  →',x,cy,w,'Map');button(ctx,'Prepare your visit  →',x,cy+60,w,'Visit pass');txt(f,'Remembered & saved',x,cy+135,w,19,c.text);list(ctx,cy+171,1);break}
 case 'Search':case 'Empty search':button(ctx,'Maria Santos  ·  Search',x,y,w,screen==='Search'?'Search':'Search',true);button(ctx,screen==='Search'?'Try a search with no results':'Clear search',x,y+60,w,screen==='Search'?'Empty search':'Search');if(screen==='Search'){txt(f,'5 sample memorials · Select Maria to continue',x,y+137,w,12,c.muted);list(ctx,y+175)}else{card(ctx,x,y+154,w,180,'No matching memorials','Try another name or lot number.');}break;
 case 'Memorial':case 'Saved memorial':{card(ctx,x,y,w,284,'Maria Santos','Always loved. Forever remembered.');txt(f,'May 12, 1945 — March 18, 2021',x+22,y+114,w-44,15,c.text);txt(f,locations[0],x+22,y+158,w-44,14,c.muted);txt(f,screen==='Saved memorial'?'Saved to your memorials':'Fictional burial record',x+22,y+213,w-44,13,c.accent);button(ctx,'Find on map  →',x,y+307,w,'Map',true);button(ctx,screen==='Saved memorial'?'Remove from saved memorials':'Save memorial',x,y+367,w,screen==='Saved memorial'?'Memorial':'Saved memorial');button(ctx,'Create visit pass',x,y+427,w,'Generated pass');button(ctx,'Back to search',x,y+487,w,'Search');break}
 case 'Map':case 'Walking route':{const h=ground(ctx,y,screen==='Walking route');txt(f,'Maria Santos · Block A · Lot 024',x,y+h+20,w,16,c.text);button(ctx,screen==='Map'?'Preview walking route  →':'Hide walking route',x,y+h+60,w,screen==='Map'?'Walking route':'Map',true);button(ctx,'Create visit pass',x,y+h+120,w,'Generated pass');txt(f,'Illustrative route only. Confirm directions at the office.',x,y+h+187,w,11,c.muted);break}
 case 'Visit pass':case 'Generated pass':{card(ctx,x,y,w,365,'Maria Santos',locations[0]);const q=box(f,'Demo pass placeholder',x+(w-174)/2,y+104,174,174,c.raised);txt(q,'DEMO\nVISIT PASS',16,36,142,22,c.accent,true);txt(q,'NOT SCANNABLE',16,122,142,10,c.muted);txt(f,screen==='Generated pass'?'EVG-2026':'Generate a pass before arrival',x+22,y+309,w-44,17,c.text);button(ctx,screen==='Generated pass'?'Try gate officer check-in  →':'Generate demo pass  →',x,y+389,w,screen==='Generated pass'?'Gate officer':'Generated pass',true);button(ctx,'View visit history',x,y+449,w,'Empty history');break}
 case 'Gate officer':case 'Invalid pass':card(ctx,x,y,w,220,'Check in a visitor','Demo pass code');txt(f,screen==='Invalid pass'?'INVALID-CODE':'EVG-2026',x+22,y+108,w-44,24,c.text);txt(f,screen==='Invalid pass'?'Pass not found. Try the sample pass.':'Sample pass ready for validation.',x+22,y+168,w-44,12,c.accent);button(ctx,screen==='Invalid pass'?'Use valid demo pass':'Validate & check in',x,y+244,w,screen==='Invalid pass'?'Gate officer':'Visit history',true);button(ctx,'Try invalid code',x,y+304,w,'Invalid pass');button(ctx,'View visitor log',x,y+364,w,'Visit history');break;
 case 'Visit history':case 'Empty history':card(ctx,x,y,w,190,screen==='Visit history'?'Visit checked in successfully':'No visits yet',screen==='Visit history'?'Jamie Dela Cruz → Maria Santos\nDemo session · EVG-2026\nStatus: Checked in':'Create a demo pass to explore your first visit.');button(ctx,'Create another visit pass',x,y+216,w,'Visit pass',true);button(ctx,'Return to overview',x,y+276,w,'Home');break;
 case 'Profile':card(ctx,x,y,w,210,'Jamie Dela Cruz','jamie@example.com\nDemo visitor account\nProfile text is editable on the Figma canvas.');button(ctx,themeLabel(ctx),x,y+234,w,'Profile',true,ctx.theme==='Dark'?'Light':'Dark');button(ctx,'Visit history',x,y+294,w,'Visit history');button(ctx,'Explore roles',x,y+354,w,'Roles');break;
 case 'Roles':[['Visitor','Home'],['Lot owner','Lot owner'],['Gate officer','Gate officer'],['Admin','Admin'],['My profile','Profile']].forEach(([label,to],i)=>button(ctx,label+'  →',x,y+i*70,w,to,i===0));break;
 case 'Admin':card(ctx,x,y,w,143,'5 burial records · 4 cemetery blocks','Sample management overview');[['Burial records','Burial records'],['Lot management','Lot management'],['Cemetery map','Map'],['Visitor logs','Visit history'],['Switch role','Roles']].forEach(([label,to],i)=>button(ctx,label+'  →',x,y+171+i*60,w,to,i===0));break;
 case 'Burial records':case 'Lot management':list(ctx,y,5);button(ctx,'Back to admin dashboard',x,y+460,w,'Admin');break;
 case 'Lot owner':card(ctx,x,y,w,219,'Block A · Lot 024','Linked memorial: Maria Santos\nGrave 01 · Occupied\nSample ownership information');button(ctx,'View memorial',x,y+243,w,'Memorial',true);button(ctx,'Locate my lot',x,y+303,w,'Map');button(ctx,'Switch role',x,y+363,w,'Roles');break;
 }
}
function themeLabel(ctx){return ctx.theme==='Dark'?'Switch to light mode':'Switch to dark mode'}
async function run(){
 const available=await figma.listAvailableFontsAsync();const choose=(family,style,fallback)=>available.find(f=>f.fontName.family===family&&f.fontName.style===style)?.fontName||fallback;
 const body=choose('Inter','Regular',{family:'Roboto',style:'Regular'});fonts={body,bold:choose('Inter','Semi Bold',choose('Inter','Bold',body)),display:choose('Georgia','Regular',choose('Noto Serif','Regular',body))};
 for(const font of Object.values(fonts))await figma.loadFontAsync(font);
 page=figma.createPage();page.name='Evergreen · Clickable prototype';await figma.setCurrentPageAsync(page);
 let row=0;for(const device of ['Desktop','Mobile'])for(const theme of ['Dark','Light']){for(let i=0;i<screens.length;i++)draw(shell(device,theme,screens[i],i,row),screens[i]);row++}
 for(const link of links){const destination=frames[link.key];if(!destination)throw new Error('Missing destination: '+link.key);await link.node.setReactionsAsync([{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',destinationId:destination.id,navigation:'NAVIGATE',transition:null,preserveScrollPosition:false}]}])}
 page.flowStartingPoints=['Desktop','Mobile'].map(device=>({nodeId:frames[`${device}/Dark/Home`].id,name:`${device} · Dark mode journey`}));
 page.selection=[frames['Desktop/Dark/Home']];figma.viewport.scrollAndZoomIntoView(page.selection);
 figma.closePlugin(`Created ${Object.keys(frames).length} editable frames and ${links.length} prototype connections. Press Present to explore.`);
}
run().catch(error=>{console.error(error);figma.closePlugin('Import interrupted: '+error.message+'. Any partially created page is retained for inspection.');});
